  void RoomObserve(string clip)
  {
   var w=shop.World;var d=w.LabDoor;var s=w.RoomAtmosphereSnapshot;int count=w.FxPool.ParticleCountForValidation(w.RoomAtmosphereOwner);
   if(!CustomerMotionFinite(d.OpenFraction)||d.OpenFraction<0||d.OpenFraction>1||!CustomerMotionFinite(s.Blend)||count<0||count>2)throw new InvalidOperationException("Room trace invalid state/budget");
   if(Vector3.Distance(d.transform.position,roomDoorRoot)>.001f||Quaternion.Angle(d.transform.rotation,roomDoorRotation)>.001f)throw new InvalidOperationException("Door root moved");
   foreach(var leaf in new[]{d.LeftLeaf,d.RightLeaf}){var c=leaf.GetComponent<BoxCollider>();if(!c||!c.enabled||c.isTrigger||Mathf.Abs(leaf.localPosition.z)>.001f||Mathf.Abs(leaf.localPosition.y)>.001f||Mathf.Abs(leaf.localPosition.x)>2.461f)throw new InvalidOperationException("Door collider/root/pocket constraint");}
   var intensities=new float[7];var colors=new Color[7];for(int i=0;i<7;i++){var light=w.RoomLightForValidation(i);intensities[i]=light?light.intensity:-1;colors[i]=light?light.color:Color.clear;}
   roomFrames.Add(new RoomFrame{clip=clip,renderFrame=Time.frameCount,realtime=Time.realtimeSinceStartup,storeTier=shop.Layout.StoreTier,labTier=shop.Layout.LabTier,phase=s.CurrentPhase.ToString(),target=s.TargetPhase.ToString(),policy=s.Policy.ToString(),fraction=d.OpenFraction,velocity=d.MotionVelocity,wantsOpen=d.WantsOpen,left=d.LeftLeaf.position,right=d.RightLeaf.position,blend=s.Blend,clock=s.Clock,working=s.Working,decorativeSuppressed=s.DecorativeVaporSuppressed,growthActive=w.LabGrowthActive,growthProgress=w.LabGrowthProgress,growthScale=w.GrowthCreatureForValidation?w.GrowthCreatureForValidation.localScale:Vector3.zero,growthParticles=w.GrowthIncubatorAmbientCount,poolActive=w.FxPool.ActiveCount,poolDropped=w.FxPool.DroppedCount,poolSpawned=w.FxPool.SpawnedCount,ambientLimit=w.FxPool.AmbientLimit,emissions=s.EmissionCount,particles=count,source=w.RoomAtmosphereSource?w.RoomAtmosphereSource.position:Vector3.zero,intensities=intensities,colors=colors});roomGeometry++;
  }
  IEnumerator RoomClip(string name,float seconds,Action<float> tick=null)
  {
   if(Application.isEditor){float start=Time.realtimeSinceStartup;while(Time.realtimeSinceStartup-start<seconds){tick?.Invoke(Time.realtimeSinceStartup-start);yield return null;RoomObserve(name);}RoomWriteTrace();yield break;}
   using(var r=new FxReviewRecorder(ShopSession.Arg("-evolutionFxReviewEncoder"),Path.Combine(evidence,name+".mp4"))){while(r.Age<seconds){tick?.Invoke(r.Age);yield return new WaitForEndOfFrame();RoomObserve(name);r.Sample();if(r.Failure!=null)throw new InvalidOperationException(r.Failure);}float deadline=Time.realtimeSinceStartup+3;while(r.Pending>0){if(Time.realtimeSinceStartup>deadline)throw new TimeoutException("Room capture drain");yield return null;}var receipt=r.Finish();File.WriteAllText(Path.Combine(evidence,name+"-frames.json"),JsonUtility.ToJson(receipt,true));Check(receipt.frames.Length>=seconds*25&&receipt.achievedFPS>=25&&receipt.missedSamples<=seconds*5,"Actual ordinary HUD room video / "+name);RoomWriteTrace();}
  }
  void RoomWriteTrace(){File.WriteAllText(Path.Combine(evidence,"room-atmosphere.json"),JsonUtility.ToJson(new RoomReceipt{frames=roomFrames.ToArray(),geometrySamples=roomGeometry},true));}
