  void RoomDoorClosedGeometry()
  {
   var d=shop.World.LabDoor;Check(d.OpenFraction==0,"Door fully closed before opaque geometry checks");
   foreach(var leaf in new[]{d.LeftLeaf,d.RightLeaf}){var c=leaf.GetComponent<BoxCollider>();Bounds rendered=new Bounds();bool found=false;foreach(var r in leaf.GetComponentsInChildren<MeshRenderer>()){if(!r.enabled||r.GetComponent<TextMesh>())continue;Check(r.sharedMaterial&&r.sharedMaterial.renderQueue<2500,"Actual merged leaf material renders opaque");if(!found){rendered=r.bounds;found=true;}else rendered.Encapsulate(r.bounds);}Check(found&&Mathf.Abs(rendered.center.x-c.bounds.center.x)<.002f&&Mathf.Abs(rendered.size.x-c.bounds.size.x)<.002f&&Mathf.Abs(rendered.size.y-c.bounds.size.y)<.002f&&rendered.size.z<.25f,"Actual merged opaque leaf matches collider span with bounded surface trim");}
   foreach(float x in new[]{-.7f,0f,.7f})foreach(int side in new[]{-1,1}){var ray=new Ray(d.transform.TransformPoint(new Vector3(x,1.4f,side)),d.transform.TransformDirection(new Vector3(0,0,-side)));bool hit=d.LeftLeaf.GetComponent<BoxCollider>().Raycast(ray,out _,2)||d.RightLeaf.GetComponent<BoxCollider>().Raycast(ray,out _,2);Check(hit,"Closed opaque physical separation both room directions x="+x+" side="+side);}
   Check(d.LeftLeaf.GetComponent<BoxCollider>().bounds.max.x>=d.RightLeaf.GetComponent<BoxCollider>().bounds.min.x,"Closed leaf center seam has no physical gap");
  }
  void RoomDoorOpenGeometry()
  {var d=shop.World.LabDoor;Check(d.OpenFraction==1,"Door reaches full open");float gap=d.RightLeaf.GetComponent<BoxCollider>().bounds.min.x-d.LeftLeaf.GetComponent<BoxCollider>().bounds.max.x;Check(gap>3.2f,"Open physical passage clears original 3.2m span");var ray=new Ray(d.transform.position+new Vector3(0,1.4f,-1),Vector3.forward);Check(!d.LeftLeaf.GetComponent<BoxCollider>().Raycast(ray,out _,2)&&!d.RightLeaf.GetComponent<BoxCollider>().Raycast(ray,out _,2),"Open leaves do not block center passage");}
